const command = String(msg.payload).trim().toUpperCase();

if (!["LOCK", "UNLOCK"].includes(command)) {
    node.warn("Invalid command: " + command);
    return null;
}

const requestId =
    "nr-" + Date.now() + "-" +
    Math.random().toString(36).slice(2, 8);

msg.payload = JSON.stringify({
    command: command,
    request_id: requestId,
    source: "node-red"
});

msg.topic = "smartlock/group23/duong2026/demo/cmd";

return msg;

let commandData;

try {
    commandData = typeof msg.payload === "string"
        ? JSON.parse(msg.payload)
        : msg.payload;
} catch (error) {
    node.warn("Invalid outgoing JSON");
    return null;
}

if (!commandData ||
    !["LOCK", "UNLOCK"].includes(commandData.command) ||
    typeof commandData.request_id !== "string" ||
    !commandData.request_id) {
    node.warn("Invalid outgoing command");
    return null;
}

// Lấy danh sách các lệnh đang chờ ACK
const pending = flow.get("pendingRequests") || {};

// Lưu thông tin theo request_id
pending[commandData.request_id] = {
    command: commandData.command,
    sent_at: Date.now()
};

flow.set("pendingRequests", pending);

node.status({
    fill: "blue",
    shape: "dot",
    text: "Pending: " + Object.keys(pending).length
});

return msg;

const TIMEOUT_MS = 8000;

// 1. Đọc ACK từ ESP32
let ack;

try {
    ack = typeof msg.payload === "string"
        ? JSON.parse(msg.payload)
        : msg.payload;
} catch (error) {
    return null;
}

// Chỉ xử lý thông điệp ACK
if (!ack || ack.type !== "ack") {
    return null;
}

// 2. Kiểm tra cấu trúc ACK
if (
    ack.source !== "esp32" ||
    ack.status !== "ACCEPTED" ||
    typeof ack.request_id !== "string" ||
    !["LOCK", "UNLOCK"].includes(ack.command)
) {
    node.warn("Invalid ACK format");
    return null;
}

// 3. Lấy danh sách lệnh đang chờ
const pending = flow.get("pendingRequests") || {};
const requestId = ack.request_id;

// Kiểm tra request_id
if (!Object.prototype.hasOwnProperty.call(pending, requestId)) {
    node.warn("Unknown or duplicate ACK: " + requestId);
    return null;
}

// Lấy thông tin lệnh gốc
const request = pending[requestId];

// 4. Kiểm tra ACK có đúng lệnh không
if (request.command !== ack.command) {
    node.warn("ACK command mismatch: " + requestId);
    return null;
}

// 5. Kiểm tra thời hạn ACK
const elapsed = Date.now() - request.sent_at;

if (!Number.isFinite(elapsed) || elapsed >= TIMEOUT_MS) {
    node.warn(
        "Late ACK ignored: " +
        requestId + " (" + elapsed + " ms)"
    );

    // Sweep Pending Timeouts sẽ xử lý TIMEOUT
    return null;
}

// 6. ACK hợp lệ: xóa lệnh khỏi danh sách chờ
delete pending[requestId];
flow.set("pendingRequests", pending);

// 7. Trả kết quả
msg.payload = {
    result: "ACK_MATCHED",
    request_id: requestId,
    command: ack.command,
    servo_target_angle: ack.servo_target_angle,
    round_trip_ms: elapsed
};

node.status({
    fill: "green",
    shape: "dot",
    text: "Matched: " + requestId
});

return msg;

const TIMEOUT_MS = 8000;
const now = Date.now();

const pending = flow.get("pendingRequests") || {};

let changed = false;

for (const [requestId, request] of Object.entries(pending)) {

    const elapsed = now - request.sent_at;

    if (elapsed >= TIMEOUT_MS) {

        node.send({
            payload: {
                result: "TIMEOUT",
                request_id: requestId,
                command: request.command,
                elapsed_ms: elapsed
            }
        });

        delete pending[requestId];
        changed = true;
    }
}

if (changed) {
    flow.set("pendingRequests", pending);
}

node.status({
    fill: "blue",
    shape: "dot",
    text: "Pending: " + Object.keys(pending).length
});

return null;
